import {
    Table,
    BooleanColumn,
    StringColumn,
    FieldNameColumn,
    IntegerColumn,
    ReferenceColumn,
    GuidColumn,
    Password2Column,
} from '@servicenow/sdk/core'

export const ldap_server_config = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'LDAP Server',
    name: 'ldap_server_config',
    schema: {
        listener: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Start a listener for this server',
                    label: 'Listener',
                    plural: 'Listeners',
                    language: 'en',
                },
            ],
        }),
        rdn: StringColumn({
            label: [
                {
                    hint: 'Starting point for searching (relative distinguished name)',
                    label: 'Starting search directory',
                    plural: 'Starting search directories',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        dn_field: FieldNameColumn({
            attributes: {
                allow_null: true,
                table: 'sys_user',
            },
            label: [
                {
                    hint: 'Field name containing DN for user for LDAP authentication',
                    label: 'DN Field',
                    plural: 'DN Fields',
                    language: 'en',
                },
            ],
        }),
        name: StringColumn({
            label: 'Name',
            unique: true,
        }),
        listen_interval: IntegerColumn({
            default: '5',
            label: [
                {
                    hint: 'Number of minutes between processing of LDAP server changes',
                    label: 'Listen interval',
                    plural: 'Listen intervals',
                    language: 'en',
                },
            ],
        }),
        system_id: StringColumn({
            label: 'System ID',
            maxLength: 100,
        }),
        read_timeout: IntegerColumn({
            default: '30',
            label: [
                {
                    hint: 'Number of seconds before a timeout on read requests',
                    label: 'Read timeout',
                    plural: 'Read timeouts',
                    language: 'en',
                },
            ],
        }),
        map: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Map',
            referenceTable: 'sys_impex_map',
        }),
        server_url: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: 'new LDAPURLUtils().getAccumURL(current.sys_id);',
            },
            label: [
                {
                    hint: 'URL to connect to server',
                    label: 'Server URL',
                    plural: 'Server URLs',
                    language: 'en',
                },
            ],
            maxLength: 1000,
            readOnly: true,
        }),
        attributes: StringColumn({
            label: [
                {
                    hint: 'Attributes that you want to retrieve from LDAP',
                    label: 'Attributes',
                    plural: 'Attributes',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        paging: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Use LDAP paging service for getting results',
                    label: 'Paging',
                    plural: 'Pagings',
                    language: 'en',
                },
            ],
        }),
        connect_timeout: IntegerColumn({
            default: '10',
            label: [
                {
                    hint: 'Number of seconds before a timeout on connection requests',
                    label: 'Connect timeout',
                    plural: 'Connect timeouts',
                    language: 'en',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        password: Password2Column({
            attributes: {
                is_legacy_password2: true,
                no_data_replicate: true,
            },
            label: [
                {
                    hint: 'Password used for logging in to LDAP server',
                    label: 'Login password',
                    plural: 'Login passwords',
                    language: 'en',
                },
            ],
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Server is active',
                    label: 'Active',
                    plural: 'Active',
                    language: 'en',
                },
            ],
        }),
        vendor: StringColumn({
            default: 'active_directory',
            dropdown: 'dropdown_without_none',
            label: 'Vendor',
        }),
        mid_server: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Specify a MID server to use for this LDAP Server',
                    label: 'MID Server',
                    plural: 'MID Servers',
                    language: 'en',
                },
            ],
            referenceTable: 'ecc_agent',
        }),
        authenticate: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Use LDAP authentication for users from this server',
                    label: 'Authenticate',
                    plural: 'Authenticates',
                    language: 'en',
                },
            ],
        }),
        ssl: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Use SSL when connecting to this server',
                    label: 'SSL',
                    plural: 'SSLs',
                    language: 'en',
                },
            ],
        }),
        dn: StringColumn({
            label: [
                {
                    hint: 'DN used for logging in to LDAP server',
                    label: 'Login distinguished name',
                    plural: 'Login distinguished names',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
    },
})
